/* Host UI boundary: event(ds, kind, args, count) with near DS offsets.
 * 0 set_role(person,value) 1 set_group(person,value) 2 portrait(x,y,person)
 * 3 attribute(value) 4 text_color(color) 5 position(x,y)
 * 6 print(format,arguments...) 7 side_color(side)
 * 8 table_columns(column,row) -> first column byte (other outputs unused)
 * 9 06db:09c8() 10 06db:0a5c(slot) 11 06db:0b04(slot) 12 06db:0d64(division)
 * 13 06db:0ea4() -> division byte 14 06db:0f26(side,kind) 15 06db:0f32(side,group)
 */
static uint16_t get16(const uint8_t* ds, uint16_t at) {
  return (uint16_t)(ds[at] | ds[(uint16_t)(at + 1)] << 8);
}
#define PERSON          uint16_t
#define WINDOW_PTR      uint16_t
#define FIELD(p, o)     ds[(uint16_t)((p) + (o))]
#define ROW             ds[0xe2f4]
#define TOP             ds[0xe2f1]
#define SIDE            ds[0x62]
#define LIST(i)         get16(ds, (uint16_t)(0xea2a + 2 * (i)))
#define WINDOW          get16(ds, 0xe2ee)
#define WIN_X(f)        get16(ds, f)
#define WIN_Y(f)        get16(ds, (uint16_t)((f) + 2))
#define WIN_COLUMN(f)   ds[get16(ds, (uint16_t)((f) + 8))]
#define ROLE_NAME(i)    get16(ds, (uint16_t)(0x3b54 + 2 * (i)))
#define OPS_FORMAT      0x4653
#define OPS_PROMPT      0x4663
#define INTEL_FORMAT    0x4689
#define INTEL_PROMPT    0x4699
#define DIVISION_FORMAT 0x46c0
#define DIVISION_SHORT  0x46d0
#define DIVISION_LONG   0x46de
#define ROLE_PROMPT     0x46ee
#define DIVISION_PROMPT 0x46fe
#define HEADER          0x471c
#define NAME_FORMAT     0x4745
#define STATS_FORMAT    0x474e
#define CALL(kind, ...)                              \
  event(ds, kind, (const uint16_t[]){ __VA_ARGS__ }, \
        (uint16_t)(sizeof((uint16_t[]){ __VA_ARGS__ }) / sizeof(uint16_t)))
#define CALL0(kind)       event(ds, kind, NULL, 0)
#define SET_ROLE(p, v)    CALL(0, p, v)
#define SET_GROUP(p, v)   CALL(1, p, (uint8_t)(v))
#define PORTRAIT(x, y, p) CALL(2, (uint16_t)(x), (uint16_t)(y), p)
#define ATTRIBUTE(v)      CALL(3, v)
#define TEXT_COLOR(c)     CALL(4, c)
#define POSITION(x, y)    CALL(5, (uint16_t)(x), (uint16_t)(y))
