#define MARK_ROLE(s)      CALL(11, (uint16_t)(s))
#define DIVISION_BOX(d)   CALL(12, (uint8_t)(d))
#define CHOOSE_DIVISION() (uint8_t)CALL0(13)
#define CLEAR_SIDE(s, k)  CALL(14, s, (uint8_t)(k))
#define CLEAR_GROUP(s, g) CALL(15, s, (uint8_t)(g))
