/* Choice callback: 0..2 staff roles, 3..6 division commanders, 11..13
 * dismiss a staff role, 14.. dismiss a division commander.
 * Returns 1 after a change, 0 when the general is already assigned.
 */
uint8_t opeu_general_assign_choice(uint8_t ds[65536], HostEvent event,
                                   uint8_t choice) {
  int     a;
  uint8_t b;
  PERSON  c;
  int     d[3];
  int     e;
  d[0] = 1;
  d[1] = 2;
  d[2] = 3;
  c    = LIST(ROW);
  if (choice > 10 || (!(FIELD(c, 0x1e) & 7) && !(FIELD(c, 0x1c) & 4))) {
    switch (choice) {
      case 0:
        SET_ROLE(c, 1);
        PORTRAIT(0x20, 0x28, c);
        ATTRIBUTE(4);
        POSITION(0x29, 0x58);
        PRINT(OPS_FORMAT, SIDE == 0 ? 6 : 5, c);
        REDRAW();
        POSITION(0x15, 0x170);
        PRINT(OPS_PROMPT);
        ATTRIBUTE(0);
        return 1;
      case 1:
        SET_ROLE(c, 2);
        PORTRAIT(0xc, 0x28, c);
        ATTRIBUTE(4);
        POSITION(0x15, 0x58);
        PRINT(INTEL_FORMAT, SIDE == 0 ? 6 : 5, c);
        REDRAW();
        POSITION(0x15, 0x170);
        PRINT(INTEL_PROMPT);
        ATTRIBUTE(0);
        return 1;
      case 2:
        SET_ROLE(c, 3);
        PORTRAIT(0x34, 0x28, c);
        ATTRIBUTE(4);
        POSITION(0x3d, 0x58);
        PRINT(DIVISION_FORMAT, SIDE == 0 ? 6 : 5, c);
        b = CHOOSE_DIVISION();
        DIVISION_BOX(b - 3);
        REDRAW();
        POSITION(0x15, 0x170);
        PRINT(DIVISION_PROMPT, b - 2);
        ATTRIBUTE(0);
        return 1;
      case 3:
      case 4:
      case 5:
      case 6:
        SET_GROUP(c, choice - 3);
        PORTRAIT(choice * 20 - 0x3a, 0x88, c);
        ATTRIBUTE(4);
        POSITION(choice * 20 - 0x31, 0x98);
        if (choice == 6)
          PRINT(DIVISION_SHORT, SIDE == 0 ? 6 : 5, c);
        else
          PRINT(DIVISION_LONG, SIDE == 0 ? 6 : 5, c);
        b = CHOOSE_DIVISION();
        if (b >= 7) {
          ATTRIBUTE(0);
          return 1;
        }
        DIVISION_BOX(b - 3);
        REDRAW();
        POSITION(0x15, 0x170);
        PRINT(DIVISION_PROMPT, b - 2);
        ATTRIBUTE(0);
        return 1;
      default:
        if (choice <= 10)
          return 0;
        /* C 6.0a: assigning a before e keeps choice in CX for both. */
        a = choice - 10;
        e = choice - 11;
        switch (a) {
          case 1:
          case 2:
          case 3:
            ATTRIBUTE(4);
            CLEAR_SIDE(SIDE, d[e]);
            MARK_ROLE(e);
            SHOW_ROLE(e);
            REDRAW();
            POSITION(0x15, 0x170);
            PRINT(ROLE_PROMPT, ROLE_NAME(e));
            ATTRIBUTE(0);
            return 1;
          default:
            ATTRIBUTE(4);
            CLEAR_GROUP(SIDE, a - 4);
            MARK_ROLE(e);
            SHOW_ROLE(e);
            REDRAW();
            POSITION(0x15, 0x170);
            PRINT(DIVISION_PROMPT, a - 3);
            ATTRIBUTE(0);
            return 1;
        }
    }
  }
  return 0;
}

/* Row-draw callback for list rows first..last (last below 255). Bit 0/1 of
 * flags draws the ability header, bit 0/2 the names.
 */
void opeu_general_list_draw_rows(uint8_t ds[65536], HostEvent event,
                                 uint8_t column, uint8_t first, uint8_t row,
                                 uint8_t last, uint8_t flags) {
  uint8_t    a, b, c, d;
  PERSON     e;
  WINDOW_PTR f;
  f = WINDOW;
  COLUMNS(column, &c, row, &b, &a);
  if (flags & 3) {
    POSITION(WIN_COLUMN(f) + c + WIN_X(f) - 0x1f, WIN_Y(f) + 1);
    SIDE_COLOR(SIDE);
    PRINT(HEADER);
  }
  for (d = first; d <= last; ++d) {
    e = LIST(d);
    /* An if/else (not continue) keeps the row index live in AX. */
    if (FIELD(e, 0x12) != 0xff) {
      if (flags & 5) {
        POSITION(WIN_X(f) + 3, (d - TOP) * 17 + WIN_Y(f) + 0x12);
        SIDE_COLOR(SIDE);
        PRINT(NAME_FORMAT, e);
      }
      POSITION(WIN_COLUMN(f) + c + WIN_X(f) - 0x1e,
               (d - TOP) * 17 + WIN_Y(f) + 0x12);
      if ((FIELD(e, 0x1c) & 4) || (FIELD(e, 0x1e) & 7))
        SIDE_COLOR(SIDE);
      else
        TEXT_COLOR(7);
      PRINT(STATS_FORMAT, FIELD(e, 0x13), FIELD(e, 0x14), FIELD(e, 0x15),
            FIELD(e, 0x16), FIELD(e, 0x18), FIELD(e, 0x19), FIELD(e, 0x1a));
    }
  }
  TEXT_COLOR(7);
}

